using System;using System.Drawing;using System.Windows.Forms;using AshkanPharmacy.Core;
namespace AshkanPharmacy.Forms { public class NotificationCenterForm:Form {
 public NotificationCenterForm(){Text=Localization.Persian?"مرکز اعلان‌ها":"Notification Center";BackColor=Color.FromArgb(228,240,243);Dock=DockStyle.Fill;FormBorderStyle=FormBorderStyle.None;PageChrome.Header(this,Text,Localization.Persian?"هشدارهای موجودی، انقضا، امنیت و عملیات":"Inventory, expiry, security and operational signals",Color.FromArgb(23,126,135),Color.FromArgb(61,82,151));Build();}
 void Build(){var h=OperationalHealthService.Check();PageChrome.Stat(this,28,160,Localization.Persian?"کم‌موجودی":"Low stock",h.LowStock.ToString(),Theme.Warning);PageChrome.Stat(this,250,160,Localization.Persian?"نزدیک انقضا":"Near expiry",h.NearExpiry.ToString(),Theme.Danger);PageChrome.Stat(this,472,160,Localization.Persian?"سامانه":"System",h.Database?"Healthy":"Attention",h.Database?Theme.Teal:Theme.Danger);var p=new RoundedPanel{Left=28,Top=275,Width=900,Height=330,Radius=18,BackColor=Theme.Card,BorderColor=Color.FromArgb(205,221,226)};Controls.Add(p);p.Controls.Add(new Label{Text=Localization.Persian?"مرکز رویدادهای قابل اقدام":"Actionable events",Left=24,Top=18,Width=400,Height=34,Font=Theme.Font(14,FontStyle.Bold),ForeColor=Theme.Navy});p.Controls.Add(new Label{Text=(h.LowStock>0?"● Low-stock replenishment required\n\n":"● Stock levels normal\n\n")+(h.NearExpiry>0?"● Near-expiry review required\n\n":"● Expiry window healthy\n\n")+"● Security & audit pipeline active",Left=26,Top=75,Width=650,Height=190,Font=Theme.Font(10),ForeColor=Theme.Teal});}
 } }